use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let n = input["n"].as_u64().unwrap();
    let start = input["start"].as_u64().unwrap();
    let edges = input["edges"].as_array().unwrap();

    let mut reachable_nodes = Vec::new();

    for edge in edges {
        let from = edge[0].as_u64().unwrap();
        let to = edge[1].as_u64().unwrap();

        if from == start {
            reachable_nodes.push(start);
        } else if to == start {
            reachable_nodes.push(to);
        }
    }

    reachable_nodes.sort_unstable();
    reachable_nodes.into_iter().collect()
}
